```c
#include <stdio.h>

// Define an error code
#define SUCCESS 0
#define ERROR 1

// Function to perform an operation that might fail
int performOperation() {
    // Simulate an operation that might fail
    if (/* some condition */) {
        return ERROR; // Return error code
    }
